WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_esc_walk_stop'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '人走梯走与人不走梯走', 'kp-trv-esc-walk-stop', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "人走梯走与人不走梯走"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推导：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "人不走梯走，梯速即为唯一的动力；人走梯走，两重动力叠加。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“小明站在扶梯上不动，1 分钟到达；如果他在扶梯上自己走，只需 20 秒”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[设总级数 S 为时间 60秒 和 20秒 的公倍数, 如 60 级] --> B[电梯速度 V梯 = S/60 = 1 级/秒]\nB --> C[合作总速度 V合 = S/20 = 3 级/秒]\nC --> D[人自己走的速度 V人 = V合 - V梯 = 2 级/秒]\nD --> E[如果问停电时人自己走要多久, 用 S / V人 求解]"}}]}$$ AS jsonb), NULL, '人走梯走与人不走梯走的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "人走梯走与人不走梯走"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_esc_walk_stop", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
